import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Mutation thresholds — SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"quality/mutation-thresholds.md","filePath":"quality/mutation-thresholds.md"}'),i={name:"quality/mutation-thresholds.md"};function s(r,e,c,n,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="mutation-thresholds-—-ssot" tabindex="-1">Mutation thresholds — SSOT <a class="header-anchor" href="#mutation-thresholds-—-ssot" aria-label="Permalink to &quot;Mutation thresholds — SSOT&quot;">​</a></h1><h2 id="why-this-file-exists" tabindex="-1">Why this file exists <a class="header-anchor" href="#why-this-file-exists" aria-label="Permalink to &quot;Why this file exists&quot;">​</a></h2><p>The Stryker rollout across kiwa&#39;s <code>@kiwa/*</code> monorepo used ad-hoc per-package thresholds up to v1.26 — <code>high 80 / low 60 / break 50</code> for <code>core</code>, <code>high 90 / low 80 / break 80</code> for <code>api</code> and <code>nextjs</code>, and no documented reason for the split. When v1.27 expands mutation testing from 22 packages to 33+, each new package needs a threshold justification that survives review.</p><p>This doc pins every package to one of four rationale tiers and encodes the mapping in each package&#39;s <code>stryker.config.mjs</code> header comment. The tiers are named after the shape of the code Stryker runs over, not the package name.</p><h2 id="tier-table" tabindex="-1">Tier table <a class="header-anchor" href="#tier-table" aria-label="Permalink to &quot;Tier table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Kill-rate <code>high</code></th><th>Kill-rate <code>low</code></th><th>Kill-rate <code>break</code></th><th>Applies to</th></tr></thead><tbody><tr><td>Core</td><td>80 %</td><td>60 %</td><td>50 %</td><td>Pure logic packages with fully deterministic tests and no external protocol drift.</td></tr><tr><td>Framework</td><td>70 %</td><td>60 %</td><td>50 %</td><td>SSR / hydration / RSC / adapter-wrapper layers where framework internals + client / server dual code paths lower the maximum practical kill-rate.</td></tr><tr><td>SaaS</td><td>65 %</td><td>55 %</td><td>50 %</td><td>Provider-specific adapters (Stripe / Paddle / Anthropic / Ably / Redis / Prisma / …) where mocks approximate a live external API and drift is expected.</td></tr><tr><td>Test type</td><td>60 %</td><td>50 %</td><td>40 %</td><td>Test harness packages (component / visual / a11y / e2e) where DOM / measurement noise + browser dependence inflates false-negative mutants.</td></tr></tbody></table><p>Kill-rate = <code>killed / (killed + survived + timeout + error)</code> as reported by Stryker&#39;s <code>json</code> reporter. <code>high</code> colours the HTML report green, <code>low</code> colours it yellow, <code>break</code> fails the mutation run.</p><h2 id="tier-assignment-—-33-plus-package-matrix" tabindex="-1">Tier assignment — 33-plus package matrix <a class="header-anchor" href="#tier-assignment-—-33-plus-package-matrix" aria-label="Permalink to &quot;Tier assignment — 33-plus package matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Tier</th><th>Threshold</th><th>Reason</th></tr></thead><tbody><tr><td><code>@kiwa/core</code></td><td>Core</td><td>80 / 60 / 50</td><td>Pure parser + pool logic every adapter depends on.</td></tr><tr><td><code>@kiwa/api</code></td><td>Core</td><td>90 / 80 / 80</td><td>HTTP request client + MSW bridge — protocol invariants.</td></tr><tr><td><code>@kiwa/data</code></td><td>Core</td><td>80 / 60 / 50</td><td>Fixture builders + assertion helpers, pure logic.</td></tr><tr><td><code>@kiwa/cli-test</code></td><td>Core</td><td>80 / 60 / 50</td><td>CLI expectation runner, pure logic.</td></tr><tr><td><code>@kiwa/cli</code></td><td>Core</td><td>80 / 60 / 50</td><td>CLI runtime for kiwa init / scaffold, pure logic.</td></tr><tr><td><code>@kiwa/observability</code></td><td>Core</td><td>80 / 60 / 50</td><td>Flaky detection + coverage gap analysis, pure logic.</td></tr><tr><td><code>@kiwa/nextjs</code></td><td>Framework</td><td>70 / 60 / 50</td><td>RSC + Server Actions + Middleware invariants. v1.27-1 rolled out with an aspirational 90 / 80 / 80 override, but the v1.27-2 baseline sweep landed at 80 % covered MSI (79.35 % total). Reverted to Framework default until follow-up tests raise the bar back to 90.</td></tr><tr><td><code>@kiwa/nuxt</code></td><td>Framework</td><td>70 / 60 / 50</td><td>SSR + hydration + Nitro adapter drift.</td></tr><tr><td><code>@kiwa/sveltekit</code></td><td>Framework</td><td>70 / 60 / 50</td><td>SSR + hydration + load / actions drift.</td></tr><tr><td><code>@kiwa/remix</code></td><td>Framework</td><td>70 / 60 / 50</td><td>SSR + loader / action + client hydration drift.</td></tr><tr><td><code>@kiwa/astro</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Islands + SSR + partial hydration drift.</td></tr><tr><td><code>@kiwa/solidstart</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Solid SSR + resource + server-function drift.</td></tr><tr><td><code>@kiwa/qwikcity</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Resumability + SSR + route loader drift.</td></tr><tr><td><code>@kiwa/edge</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Workers / Deno / Bun edge runtimes with divergent APIs.</td></tr><tr><td><code>@kiwa/solidjs</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Solid signal + resource + SSR drift.</td></tr><tr><td><code>@kiwa/fresh</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Deno Fresh islands + SSR drift.</td></tr><tr><td><code>@kiwa/hono</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Hono edge + node adapter drift.</td></tr><tr><td><code>@kiwa/auth</code></td><td>Framework</td><td>70 / 60 / 50</td><td>Adapter wraps NextAuth v5 / Lucia v3 / Better Auth / Clerk / Auth0 / Supabase Auth — SSR + RSC + provider drift.</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Anthropic / OpenAI / Vercel AI SDK / LangChain — provider API surfaces evolve rapidly.</td></tr><tr><td><code>@kiwa/payment</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Stripe / Paddle / Lemon Squeezy — webhook shape + billing semantics drift.</td></tr><tr><td><code>@kiwa/queue</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>BullMQ / Inngest / Cloudflare Queues / SQS / RabbitMQ — provider transport + semantics drift. v1.27-3 baseline mutates <code>sandbox-queue.js</code> only; <code>testcontainers-queue.js</code> is excluded because its assertions only fire against live containers (0 covered mutants under the unit suite).</td></tr><tr><td><code>@kiwa/cache</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Redis / KeyDB / Memcached — client library + protocol drift. v1.27-3 baseline mutates <code>in-memory-cache.js</code> only; <code>testcontainers-cache.js</code> is excluded for the same reason as queue.</td></tr><tr><td><code>@kiwa/streaming</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Kafka / NATS / Redpanda with DLQ + exactly-once semantics.</td></tr><tr><td><code>@kiwa/realtime</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Supabase Realtime / Ably / Pusher / Socket.io — WebSocket API drift. v1.27-3 baseline mutates <code>engine.js</code> / <code>fidelity.js</code> / <code>ably.js</code> only; <code>pusher.js</code> + <code>socketio.js</code> require a live provider socket to exercise, and <code>report.js</code> is a thin adapter over <code>@kiwa/quality-metrics</code> (mutation-tested there).</td></tr><tr><td><code>@kiwa/mcp</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>MCP JSON-RPC protocol + transport drift.</td></tr><tr><td><code>@kiwa/agent</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>LangGraph + OpenAI Assistants v2 — graph + polling semantics drift.</td></tr><tr><td><code>@kiwa/search</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Algolia / Meilisearch / Typesense — index + query fidelity drift.</td></tr><tr><td><code>@kiwa/orm</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>Prisma / Drizzle / Kysely — SQL dialect + query planner drift.</td></tr><tr><td><code>@kiwa/dapp</code></td><td>SaaS</td><td>65 / 55 / 50</td><td>viem + anvil + wallet fixture — chain protocol + wallet inject drift.</td></tr><tr><td><code>@kiwa/ui</code></td><td>Test type</td><td>60 / 50 / 40</td><td>Vue / Solid / Lit / Qwik / Angular DOM harness — jsdom + framework noise.</td></tr><tr><td><code>@kiwa/a11y</code></td><td>Test type</td><td>60 / 50 / 40</td><td>axe-core WCAG 2.1 AA — measurement noise + jsdom limits.</td></tr><tr><td><code>@kiwa/visual</code></td><td>Test type</td><td>60 / 50 / 40</td><td>Screenshot + baseline / diff / accept — image diff tolerance.</td></tr><tr><td><code>@kiwa/component</code></td><td>Test type</td><td>60 / 50 / 40</td><td>Storybook + Playwright CT + Chromatic — DOM + visual noise.</td></tr><tr><td><code>@kiwa/e2e</code></td><td>Test type</td><td>60 / 50 / 40</td><td>Playwright fixture + test env — browser fixture noise.</td></tr></tbody></table><p>Any future adapter starts by picking the tier its code most resembles. If none fits, add a new tier here first, then the config.</p><h2 id="how-each-package-encodes-this" tabindex="-1">How each package encodes this <a class="header-anchor" href="#how-each-package-encodes-this" aria-label="Permalink to &quot;How each package encodes this&quot;">​</a></h2><p>Every <code>packages/*/stryker.config.mjs</code> starts with a header comment that names the tier and links back to this doc:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * Mutation testing config for @kiwa/&lt;name&gt;.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * Threshold: &lt;tier&gt; tier (high N / low N / break N) — &lt;one-line reason&gt;.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * SSOT: docs/quality/mutation-thresholds.md § &lt;tier&gt; tier.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> */</span></span></code></pre></div><p>The comment is the on-the-spot receipt. This doc is the shared law.</p><h2 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to &quot;Overrides&quot;">​</a></h2><p>A package may sit one tier stricter than its default (e.g. <code>@kiwa/api</code> picks Core-strict 90 / 80 / 80 because its historical bar already met it). Stricter overrides do not need approval — they raise the floor. A looser override requires a one-line justification in the PR body of the change that introduces it, and must not drop below the tier&#39;s <code>break</code> threshold.</p><h2 id="baseline-snapshots" tabindex="-1">Baseline snapshots <a class="header-anchor" href="#baseline-snapshots" aria-label="Permalink to &quot;Baseline snapshots&quot;">​</a></h2><p>Each package writes a per-package baseline JSON to <code>.mutation-baseline/&lt;pkg&gt;.json</code> (folder is tracked). The baseline is the last known green mutation report — kill-rate + surviving-mutant list + timestamp. <code>pnpm test:mutation</code> compares against the baseline to surface regressions. Baseline refresh happens in-PR when kill-rate improves, and is written by the same PR that raises test coverage — never as a standalone commit.</p><h2 id="_12-axis-release-gate-integration-v1-27-4" tabindex="-1">12-axis release gate integration (v1.27-4) <a class="header-anchor" href="#_12-axis-release-gate-integration-v1-27-4" aria-label="Permalink to &quot;12-axis release gate integration (v1.27-4)&quot;">​</a></h2><p>v1.27-4 promotes the mutation kill rate to a first-class 12th axis in the release gate. <code>@kiwa/quality-metrics</code> exposes three new symbols so downstream apps can opt in:</p><ul><li><code>DEFAULT_MUTATION_TIER_THRESHOLDS</code> — the SSOT table (<code>core: 80 / framework: 70 / saas: 65 / test-type: 60</code>), a <code>Readonly&lt;Record&lt;MutationTier, number&gt;&gt;</code> that mirrors the tier <code>high</code> column above.</li><li><code>resolveMutationTier(label)</code> — normalises the verbal tier label (<code>Core</code> / <code>Framework</code> / <code>SaaS</code> / <code>Test type</code>) written in <code>.mutation-baseline/*.json</code> into the machine <code>MutationTier</code> enum (<code>core</code> / <code>framework</code> / <code>saas</code> / <code>test-type</code>). Case-insensitive, trim-tolerant.</li><li><code>assertMutationTier({ metric, tier, threshold? })</code> — asserts <code>metric.killRate &gt;= threshold ?? DEFAULT_MUTATION_TIER_THRESHOLDS[tier]</code>. Zero-mutation metrics throw (<code>no mutation signal</code>) so an empty test suite never silently passes.</li></ul><p><code>evaluateReleaseGate</code> gains an optional third parameter:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">evaluateReleaseGate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(report, thresholdOverrides, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mutationTier: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;saas&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// required to enable the 12th axis</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mutationTierThreshold: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// optional looser override (e.g. auth, cache, realtime, orm)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>When <code>mutationTier</code> is omitted the verdict stays at 7 (non-AI-LLM) or 11 (AI-LLM) axes for backward compatibility. When present the verdict count grows by 1 (<code>axesEvaluated</code> becomes 8 or 12) and any threshold miss surfaces as a <code>mutation.tier</code> blocker alongside the legacy <code>mutation.killRate</code> axis (both axes coexist so v1.11 consumers keep the old shape).</p><p>The three v1.26 dogfood apps (<code>dogfood-postgres-cdc-outbox-app</code>, <code>dogfood-mysql-rls-tenant-app</code>, <code>dogfood-vector-search-app</code>) pass <code>mutationTier: &#39;saas&#39;</code> through their <code>runFidelityHarness</code> input so their <code>evaluateReleaseGate</code> invocation exercises the 12-axis path. <code>dogfood-storybook-design-system</code> (component, <code>test-type</code> tier) exposes the same optional field so a v1.27-5 follow-up can flip it on without another wire change.</p><p><code>scripts/check-mutation-gates.mjs</code> follows the same shape: the top of the file exports <code>PACKAGE_TIER</code>, <code>TIER_THRESHOLD</code>, and <code>thresholdFor()</code> so tests and neighbouring tooling read the exact same tier map instead of re-deriving it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>docs/quality/release-gate.md</code> — 12-axis release gate (mutation axis has its own bar of <code>≥ 60 %</code> used at the release-gate layer, above per-package <code>break</code>; the tier-aware axis added in v1.27-4 is the 12th).</li><li><code>docs/quality/perf-thresholds.md</code> — perf p95 SSOT (three-rationale model this file is patterned after).</li><li><code>packages/quality-metrics/src/gate.ts</code> — <code>DEFAULT_MUTATION_TIER_THRESHOLDS</code>, <code>assertMutationTier</code>, <code>resolveMutationTier</code>, and the 12-axis extension of <code>evaluateReleaseGate</code>.</li><li><code>packages/*/stryker.config.mjs</code> — per-package configs.</li><li><code>scripts/check-mutation-gates.mjs</code> — CI gate; <code>PACKAGE_TIER</code> / <code>TIER_THRESHOLD</code> / <code>thresholdFor()</code> exports.</li><li>root <code>package.json</code> <code>test:mutation</code> script — pnpm filter list covering all packages in this doc.</li></ul>`,28)])])}const k=t(i,[["render",s]]);export{u as __pageData,k as default};
